// 文件: utils/device_id.js
// 设备码生成与归一化统一工具
// 公式: (serial × 9857 + 1337) × 8191 − 2048，再以 32 字符表编码为 12 位并加连字符
// 供 home.js / activation_code.js / activation_test.js 共用，避免多处重复实现导致漂移。

const P1 = 9857;
const A1 = 1337;
const P2 = 8191;
const S1 = 2048;

// 去掉易混淆字符 0/1/I/O 的 32 字符表
const CHAR_MAP = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
const BASE = CHAR_MAP.length;

// 将数字编码为 12 位字符并格式化为 XXXX-XXXX-XXXX
function encodeNumber(num) {
  if (num === 0) return '2222-2222-2222';
  let result = '';
  let tempNum = num;
  while (tempNum > 0) {
    result = CHAR_MAP[tempNum % BASE] + result;
    tempNum = Math.floor(tempNum / BASE);
  }
  while (result.length < 12) {
    result = '2' + result;
  }
  return `${result.substring(0, 4)}-${result.substring(4, 8)}-${result.substring(8, 12)}`;
}

// 由 6 位 serial 生成设备码（带连字符的展示格式）
function generateDeviceId(serialNumber) {
  let result = serialNumber;
  result = (result * P1) + A1;
  result = (result * P2) - S1;
  return encodeNumber(result);
}

// 归一化为紧凑形式（大写、去连字符/斜杠/空白），用于比对与购买链接
function normalizeDeviceCode(raw) {
  return String(raw || '').trim().toUpperCase().replace(/[-/\s]/g, '');
}

// 归一化为带连字符的 12 位展示格式；长度非 12 返回空串
function formatDeviceCode(raw) {
  const norm = normalizeDeviceCode(raw);
  if (norm.length !== 12) return '';
  return `${norm.substring(0, 4)}-${norm.substring(4, 8)}-${norm.substring(8, 12)}`;
}

// 生成用于日志脱敏的掩码形式
function maskDeviceCode(code) {
  const norm = normalizeDeviceCode(code);
  if (norm.length !== 12) return norm;
  return `${norm.slice(0, 4)}...${norm.slice(8)}`;
}

// 校验是否为 6 位纯数字激活码
function isSixDigits(value) {
  return /^\d{6}$/.test(value);
}

export {
  encodeNumber,
  generateDeviceId,
  normalizeDeviceCode,
  formatDeviceCode,
  maskDeviceCode,
  isSixDigits
};

