function parseApiLevel(raw) {
  const text = String(raw || '').trim();
  if (!text) return [0, 0, 0];
  const parts = text.split(/[^\d]+/).filter(Boolean).map((v) => parseInt(v, 10));
  const major = Number.isFinite(parts[0]) ? parts[0] : 0;
  const minor = Number.isFinite(parts[1]) ? parts[1] : 0;
  const patch = Number.isFinite(parts[2]) ? parts[2] : 0;
  return [major, minor, patch];
}

function isApiAtLeast(requiredMajor, requiredMinor) {
  try {
    const { minAPI } = getSystemInfo();
    const [major, minor] = parseApiLevel(minAPI);
    if (major > requiredMajor) return true;
    if (major < requiredMajor) return false;
    return minor >= requiredMinor;
  } catch (e) {
    return false;
  }
}

function isOsAtLeast(requiredMajor, requiredMinor) {
  try {
    const { osVersion } = getSystemInfo();
