    if (major > requiredMajor) return true;
    if (major < requiredMajor) return false;
    return minor >= requiredMinor;
  } catch (e) {
    return false;
  }
}

function supportsCloudActivation() {
  const apiOk = isApiAtLeast(3, 6);
  const osOk = isOsAtLeast(3, 6);
  return apiOk || osOk;
}



