   429→      const target = (rem / DURATION_SEC) * 360;
   430→      animAngle += (target - animAngle) * 0.12;
   431→      this.state.ringWidget.setProperty(prop.MORE, { start_angle: 0, end_angle: Math.max(0, animAngle) });
   432→    }, 50);
   433→
   434→    const tick = () => {
   435→      const m = Math.floor(rem / 60), s = rem % 60;
   436→      this.state.countdownText.setProperty(prop.TEXT, m + ':' + s.toString().padStart(2, '0'));
   437→      
   438→      // 在 DEBUG_MODE 下，直接显示虚拟心率数据
   439→      let displayBpm;
   440→      if (DEBUG_MODE) {
   441→        displayBpm = VIRTUAL_HR_DATA[Math.floor((DURATION_SEC - rem) / (DURATION_SEC / VIRTUAL_HR_DATA.length)) % VIRTUAL_HR_DATA.length];
