// 文件: utils/trial.js
// 试用次数管理：未激活用户可免费试用 4 次手动把脉
// 次数存于 system.json 的 trial_remaining 键（与激活状态同一存储，卸载同步重置）。
// 已激活用户不受次数限制；测量成功才扣次，失败/闹钟自动测量不扣。

import { Storage } from './storage';

const SYSTEM_FILE = 'system.json';
const ACTIVATION_STATUS_KEY = 'activation_status';
const TRIAL_REMAINING_KEY = 'trial_remaining';
const TRIAL_TOTAL = 4;

// 查询试用状态：callback({ activated, remaining })
// 未激活且从未发放过（存量体验用户/新用户）时自动补发 TRIAL_TOTAL 次
function getTrialStatus(callback) {
  Storage.get(SYSTEM_FILE, (err, config) => {
    const activated = !!config && config[ACTIVATION_STATUS_KEY] === 'activated';
    if (activated) {
      callback({ activated: true, remaining: -1 });
      return;
    }
    const raw = config ? config[TRIAL_REMAINING_KEY] : undefined;
    if (raw === undefined || raw === null) {
      // 首次检查：自动发放试用额度
      Storage.patch(SYSTEM_FILE, { [TRIAL_REMAINING_KEY]: TRIAL_TOTAL }, () => {
        callback({ activated: false, remaining: TRIAL_TOTAL });
      });
      return;
    }
    const remaining = parseInt(raw, 10);
    callback({ activated: false, remaining: isNaN(remaining) ? 0 : remaining });
  });
}

// 扣减 1 次试用（下限 0），callback(remaining) 返回扣减后剩余次数
function consumeTrial(callback) {
  Storage.getField(SYSTEM_FILE, TRIAL_REMAINING_KEY, (err, raw) => {
    let remaining = parseInt(raw, 10);
    if (isNaN(remaining)) remaining = TRIAL_TOTAL;
    remaining = Math.max(0, remaining - 1);
    Storage.patch(SYSTEM_FILE, { [TRIAL_REMAINING_KEY]: remaining }, () => {
      if (callback) callback(remaining);
    });
  });
}

// 显式发放试用额度（OOBE 免费体验入口调用）；已发放过则不重复发放
function grantTrialIfAbsent(callback) {
  Storage.getField(SYSTEM_FILE, TRIAL_REMAINING_KEY, (err, raw) => {
    if (raw !== undefined && raw !== null) {
      if (callback) callback();
      return;
    }
    Storage.patch(SYSTEM_FILE, { [TRIAL_REMAINING_KEY]: TRIAL_TOTAL }, () => {
      if (callback) callback();
    });
  });
}

export {
  TRIAL_TOTAL,
  getTrialStatus,
  consumeTrial,
  grantTrialIfAbsent
};

