// 临时测试：模拟 Storage 验证 trial 逻辑闭环
const db = {};
const Storage = {
  get: (f, cb) => cb(null, db[f] || null),
  patch: (f, p, cb) => { db[f] = Object.assign(db[f] || {}, p); cb && cb(); },
  getField: (f, k, cb) => { const d = db[f]; cb(null, d && typeof d === 'object' ? d[k] : null); }
};
const SF = 'system.json', AK = 'activation_status', TK = 'trial_remaining', TOTAL = 4;

function getTrialStatus(cb) {
  Storage.get(SF, (e, c) => {
    const act = !!c && c[AK] === 'activated';
    if (act) return cb({ activated: true, remaining: -1 });
    const raw = c ? c[TK] : undefined;
    if (raw === undefined || raw === null) {
      return Storage.patch(SF, { [TK]: TOTAL }, () => cb({ activated: false, remaining: TOTAL }));
    }
    const r = parseInt(raw, 10);
    cb({ activated: false, remaining: isNaN(r) ? 0 : r });
  });
}
function consumeTrial(cb) {
  Storage.getField(SF, TK, (e, raw) => {
    let r = parseInt(raw, 10);
    if (isNaN(r)) r = TOTAL;
    r = Math.max(0, r - 1);
    Storage.patch(SF, { [TK]: r }, () => cb && cb(r));
  });
}
function grantTrialIfAbsent(cb) {
  Storage.getField(SF, TK, (e, raw) => {
    if (raw !== undefined && raw !== null) return cb && cb();
    Storage.patch(SF, { [TK]: TOTAL }, () => cb && cb());
  });
}

grantTrialIfAbsent(() => {
  console.log('1) OOBE grant:', JSON.stringify(db[SF]));
  let n = 0;
  const loop = () => {
    getTrialStatus((st) => {
      if (st.remaining > 0) {
        consumeTrial((r) => { n++; console.log('   measure #' + n + ' ok, remaining:', r); loop(); });
      } else {
        console.log('2) attempt #' + (n + 1) + ' rejected, remaining =', st.remaining);
        grantTrialIfAbsent(() => {
          console.log('3) re-grant does NOT reset:', db[SF][TK]);
          db[SF][AK] = 'activated';
          getTrialStatus((st2) => console.log('4) activated bypass:', JSON.stringify(st2)));
        });
      }
    });
  };
  loop();
});

// 存量体验用户场景：无 trial 键，首次门禁检查自动补发
const db2bak = db[SF]; db[SF] = { experience_mode: '1' };
getTrialStatus((st) => console.log('5) legacy user auto-grant:', JSON.stringify(st), 'stored:', db[SF][TK]));
db[SF] = db2bak;

